def planes(A,n=24):
    ev,V=np.linalg.eig(A)
    idx=np.argsort(-abs(ev)); out=[]
    for i in idx:
        if ev[i].imag>1e-6:
            v=V[:,i]; P=np.stack([v.real,v.imag],1); q,_=np.linalg.qr(P)
            out.append((np.degrees(np.angle(ev[i])),abs(ev[i]),q))
        if len(out)>=n: break
    return out
